INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Vorabversion immer fehlerfrei ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann kleinere Fehler enthalten"}, {"text": "Ja", "correct": false, "because": "Letzte Tests finden oft Bugs"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase folgt typischerweise auf eine Beta-Version?', 3, '[{"text": "Release Candidate", "correct": true, "because": "Nächster Schritt zur Stabilisierung"}, {"text": "Alpha", "correct": false, "because": "Frühere Phase"}, {"text": "Production", "correct": false, "because": "Finale Freigabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine Testversion stabil?', 5, '[{"text": "Keine Showstopper-Bugs", "correct": true, "because": "Kritische Fehler ausgeschlossen"}, {"text": "Feature-Komplettheit", "correct": true, "because": "Alle Funktionen vorhanden"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht primär relevant"}, {"text": "Farbschema", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Vorabversion ist feature-komplett. b) Sie wird öffentlich verteilt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, meist intern getestet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Vorbereitung einer stabilen Version?', 4, '[{"text": "Regressionstests", "correct": false, "because": "Sichern Funktionalität"}, {"text": "Benutzerfeedback", "correct": false, "because": "Verbessert Qualität"}, {"text": "Marketingkampagne", "correct": true, "because": "Nicht Teil des Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Testversion direkt in Produktion geht?', 2, '[{"text": "Nein", "correct": true, "because": "Nur nach erfolgreichen Tests"}, {"text": "Ja", "correct": false, "because": "Erst finale Freigabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verfahren stellt die Qualität einer Vorabversion sicher?', 4, '[{"text": "End-to-End-Tests", "correct": true, "because": "Prüft Gesamtfunktion"}, {"text": "Code-Optimierung", "correct": false, "because": "Sekundär"}, {"text": "Dokumentation", "correct": false, "because": "Unterstützend, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Vorabversion dasselbe wie eine Beta ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Stabiler als Beta, näher an Release"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Testphasen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wer testet eine solche Version meistens?', 2, '[{"text": "Interne Tester", "correct": true, "because": "Kleine, erfahrene Gruppe"}, {"text": "Öffentlichkeit", "correct": false, "because": "Zu früh für breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Version bereit für die Freigabe?', 5, '[{"text": "Stabilität", "correct": true, "because": "Minimiert Abstürze"}, {"text": "Keine kritischen Bugs", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Schnelle Installation", "correct": false, "because": "Sekundär"}, {"text": "Bunte UI", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung einer stabilen Version?', 4, '[{"text": "Fehlerbehebung", "correct": true, "because": "Sichert Qualität"}, {"text": "Neue Features", "correct": false, "because": "Zu spät dafür"}, {"text": "Schnelles Release", "correct": false, "because": "Qualität vor Tempo"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Testversion braucht Feedback. b) Sie enthält oft neue Features.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, feature-komplett"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Vorabversion?', 3, '[{"text": "Testumgebung", "correct": false, "because": "Sichert Stabilität"}, {"text": "Fehlerprotokolle", "correct": false, "because": "Hilft bei Bugfixing"}, {"text": "Werbekampagne", "correct": true, "because": "Nicht Teil der Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine stabile Version teste?', 4, '[{"text": "Automatisierte Tests und Feedback", "correct": true, "because": "Deckt Fehler ab"}, {"text": "Nur manuelle Checks", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Öffentliche Beta", "correct": false, "because": "Zu früh"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Versionen immer öffentlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Oft intern oder eingeschränkt"}, {"text": "Ja", "correct": false, "because": "Nicht immer öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, eine Version zu stabilisieren?', 3, '[{"text": "Code-Freeze", "correct": true, "because": "Verhindert neue Fehler"}, {"text": "Feature-Entwicklung", "correct": false, "because": "Zu spät"}, {"text": "Manuelle Dokumentation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird eine Testversion immer zur finalen Version?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei bestandener Prüfung"}, {"text": "Ja", "correct": false, "because": "Bugs können Änderungen erfordern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tests sind für eine Vorabversion entscheidend?', 5, '[{"text": "Regressionstests", "correct": true, "because": "Sichern bestehende Funktionen"}, {"text": "Stresstests", "correct": true, "because": "Prüfen Belastbarkeit"}, {"text": "UI-Tests", "correct": false, "because": "Sekundär"}, {"text": "Marketing-Tests", "correct": false, "because": "Nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Freigabe einer Version unwichtig?', 3, '[{"text": "Stabilitätsprüfung", "correct": false, "because": "Kern der Qualität"}, {"text": "Fehlerbehebung", "correct": false, "because": "Sichert Zuverlässigkeit"}, {"text": "Teamfeier", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ein kritischer Fehler gefunden wird?', 4, '[{"text": "Bugfix und neuen Kandidaten erstellen", "correct": true, "because": "Sichert Stabilität"}, {"text": "Fehler ignorieren", "correct": false, "because": "Risiko für Release"}, {"text": "Direkt veröffentlichen", "correct": false, "because": "Qualitätsverlust"}]');
